mapper.select:
SELECT aa.* FROM ( SELECT TRD_MATCH_INFO.MATCH_TYPE matchType, '01' tradeType, TRD_MATCH_INFO.Seqno seqno, TRD_MATCH_INFO.Entrust_Id entrustId, TRD_PRODUCT_DEAL_PRE.TRADE_MARKET tradeMarket, null invManagerId, TRD_MATCH_INFO.PRE_TRADE_ID preTradeId, ptl_portfolio.Portfolio_Id portfolioId, ptl_portfolio.portfolio_name portfolioName, TRD_MATCH_INFO.CSTP_TRADE_ID cstpTradeId, TRD_PRODUCT_DEAL_PRE.finprod_type2 finprodType, if(TRD_PRODUCT_DEAL_PRE.finprod_type2= 'F01', fin_product.FINPROD_ID, TRD_MATCH_INFO.PRE_TRADE_ID) finprodId, if(TRD_PRODUCT_DEAL_PRE.finprod_type2= 'F01', fin_product.FINPROD_MARKET_ID, TRD_MATCH_INFO.PRE_TRADE_ID) finprodMarketId, if(TRD_PRODUCT_DEAL_PRE.finprod_type2= 'F01',fin_product.finprod_abbr, null) finprodAbbr, TRD_PRODUCT_DEAL_PRE.ps ps, case when TRD_PRODUCT_DEAL_PRE.finprod_type2='F01' THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'PS' AND ITEM_CODE = TRD_PRODUCT_DEAL_PRE.ps) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'BACK_LEND_DIRECTION' AND ITEM_CODE = TRD_PRODUCT_DEAL_PRE.PS) END otherPs, TRD_PRODUCT_DEAL_PRE.Inv_Aim invAim, TRD_MATCH_INFO.match_num prinAmt, if(TRD_PRODUCT_DEAL_PRE.finprod_type2='F01', T1.unit_cprice, IFNULL(T1.RATE,0) * 100) unitCprice, TRD_PRODUCT_DEAL_PRE.FPRICE_AMT fpriceAmt, TRD_PRODUCT_DEAL_PRE.YIELD matureYield, TRD_PRODUCT_DEAL_PRE.Exer_Yield exerYield, TRD_PRODUCT_DEAL_PRE.Trade_Date tradeDate, case when TRD_PRODUCT_DEAL_PRE.Settle_Speed= 0 then '01' when TRD_PRODUCT_DEAL_PRE.Settle_Speed= 1 then '02' when TRD_PRODUCT_DEAL_PRE.Settle_Speed= 2 then '03' end settleSpreed, T1.UNIT_INT unitInt, T1.INT_AMT intAmt, if(TRD_PRODUCT_DEAL_PRE.finprod_type2='F01', TRD_PRODUCT_DEAL_PRE.TRADE_AMT, TRD_PRODUCT_DEAL_PRE.TRADE_AMT) tradeAmt, TRD_PRODUCT_DEAL_PRE.Sec_Manage_Acct_Id secAcctId, (select sec_acct_name from STL_SEC_ACCT_INFO where sec_acct_id=TRD_PRODUCT_DEAL_PRE.Sec_Manage_Acct_Id) secAcctName, TRD_PRODUCT_DEAL_PRE.Trade_Plat tradePlat, TRD_PRODUCT_DEAL_PRE.Chl_Id chlId, TRD_PRODUCT_DEAL_ADD_PRE.Term_Type termType, null assetType1, null priceMode, T1.REPO_TERM repoTerm, T1.REPO_TERM actCapDays, TRD_PRODUCT_DEAL_PRE.TOTLE_TRADE_ID totleTradeId, if(TRD_PRODUCT_DEAL_PRE.finprod_type2='F01', null, IFNULL(T1.PRIN_AMT,0) + IFNULL(T1.INT_AMT, 0)) mdateSettleAmt from TRD_MATCH_INFO left join TRD_PRODUCT_DEAL_PRE on TRD_PRODUCT_DEAL_PRE.TRADE_ID = TRD_MATCH_INFO.Pre_Trade_Id left join TRD_PRODUCT_DEAL_ADD_PRE on TRD_PRODUCT_DEAL_ADD_PRE.TRADE_ID = TRD_PRODUCT_DEAL_PRE.Trade_Id left join ptl_portfolio on TRD_PRODUCT_DEAL_ADD_PRE.portfolio_id = ptl_portfolio.Portfolio_Id left join fin_product on fin_product.finprod_id = TRD_PRODUCT_DEAL_PRE.Finprod_Id left join TRD_FIN_PRODUCT_DEAL_TOTAL T1 on T1.TOTLE_TRADE_ID = TRD_PRODUCT_DEAL_PRE.TOTLE_TRADE_ID
TRD_MATCH_INFO.PRE_TRADE_ID is not null and TRD_MATCH_INFO.Entrust_Id is null
AND TRD_PRODUCT_DEAL_PRE.finprod_type2 IN(
#{item}
)
and not exists( select 1 from TRD_PRODUCT_DEAL d1, TRD_PRODUCT_DEAL_ADD d2 where d1.TRADE_ID = d2.TRADE_ID and d1.F_TRADE_ID = TRD_MATCH_INFO.CSTP_TRADE_ID and d1.TRADE_STATUS = '01' and d2.ENTRUST_ID is null and not exists( select 1 from TRD_PRODUCT_DEAL dd where dd.P_TRADE_ID = d1.TRADE_ID and dd.TRADE_STATUS = '03' ) )
UNION ALL select TRD_MATCH_INFO.MATCH_TYPE matchType, '02' tradeType, TRD_MATCH_INFO.Seqno seqno, TRD_MATCH_INFO.ENTRUST_ID entrustId, ETR_ENTRUST.TRADE_MARKET tradeMarket, ETR_ENTRUST.INV_MANAGER_ID invManagerId, TRD_MATCH_INFO.PRE_TRADE_ID preTradeId, ptl_portfolio.Portfolio_Id portfolioId, ptl_portfolio.portfolio_name portfolioName, TRD_MATCH_INFO.CSTP_TRADE_ID cstpTradeId, ETR_ENTRUST_ADD.ASSET_TYPE finprodType, if(ETR_ENTRUST_ADD.ASSET_TYPE= 'F01', fin_product.FINPROD_ID, TRD_MATCH_INFO.ENTRUST_ID) finprodId, if(ETR_ENTRUST_ADD.ASSET_TYPE= 'F01', fin_product.FINPROD_MARKET_ID, TRD_MATCH_INFO.ENTRUST_ID) finprodMarketId, if(ETR_ENTRUST_ADD.ASSET_TYPE= 'F01', fin_product.finprod_abbr, null) finprodAbbr, ETR_ENTRUST.Ps ps, CASE WHEN ETR_ENTRUST_ADD.ASSET_TYPE IN ('F07') THEN (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'BACK_LEND_DIRECTION' AND ITEM_CODE = ETR_ENTRUST_ADD.BUSI_PS) ELSE (SELECT ITEM_VALUE FROM sys_datadict_list WHERE DICT_CODE = 'PS' AND ITEM_CODE = ETR_ENTRUST.PS) END AS otherPs, ETR_ENTRUST.Inv_Aim invAim, TRD_MATCH_INFO.match_num prinAmt, if(ETR_ENTRUST_ADD.ASSET_TYPE= 'F01', ETR_ENTRUST.Price, IFNULL(ETR_ENTRUST.Price,0) * 100) unitCprice, null fpriceAmt, ETR_ENTRUST_ADD.Mature_Yield matureYield, ETR_ENTRUST_ADD.Exer_Yield exerYield, TRD_MATCH_INFO.TRADE_DATE tradeDate, case when ETR_ENTRUST_ADD.SETTLE_SPREED=0 then '01' when ETR_ENTRUST_ADD.SETTLE_SPREED=1 then '02' when ETR_ENTRUST_ADD.SETTLE_SPREED=2 then '03' end settleSpreed, null unitInt, null intAmt, TRD_MATCH_INFO.match_num tradeAmt, ETR_ENTRUST_add.Sec_Acct_Id secAcctId, (select sec_acct_name from STL_SEC_ACCT_INFO where sec_acct_id=ETR_ENTRUST_add.Sec_Acct_Id) secAcctName, ETR_ENTRUST.Trade_Plat tradePlat, ETR_ENTRUST.Chl_Id chlId, ETR_ENTRUST_ADD.TERM_TYPE termType, ETR_ENTRUST_ADD.ASSET_TYPE1 assetType1, ETR_ENTRUST.PRICE_MODEL priceMode, ETR_ENTRUST_ADD.TERM_DAYS repoTerm, INTERF_CSTP_TRADE.cashHoldingDays actCapDays, null totleTradeId, null mdateSettleAmt from TRD_MATCH_INFO left join INTERF_CSTP_TRADE on INTERF_CSTP_TRADE.EXECID = TRD_MATCH_INFO.Cstp_Trade_Id left join INTERF_OPICS_TRAD_REPO on INTERF_OPICS_TRAD_REPO.oritradeid = TRD_MATCH_INFO.Cstp_Trade_Id left join INTERF_TRAD_SECDEAL on INTERF_TRAD_SECDEAL.FEDEALNO = TRD_MATCH_INFO.Cstp_Trade_Id left join ETR_ENTRUST on ETR_ENTRUST.ENTRUST_ID = TRD_MATCH_INFO.ENTRUST_ID left join ETR_ENTRUST_ADD on ETR_ENTRUST_ADD.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join ptl_portfolio on ptl_portfolio.portfolio_id = ETR_ENTRUST.Portfolio_Id left join fin_product on fin_product.finprod_id = ETR_ENTRUST.Finprod_Id
TRD_MATCH_INFO.ENTRUST_ID is not null and TRD_MATCH_INFO.Pre_Trade_Id is null
AND ETR_ENTRUST_ADD.ASSET_TYPE IN(
#{item}
)
and not exists( select 1 from TRD_PRODUCT_DEAL d1, TRD_PRODUCT_DEAL_ADD d2 where d1.TRADE_ID = d2.TRADE_ID and d1.F_TRADE_ID = TRD_MATCH_INFO.CSTP_TRADE_ID and d1.TRADE_STATUS = '01' and d2.ENTRUST_ID = TRD_MATCH_INFO.ENTRUST_ID and not exists( select 1 from TRD_PRODUCT_DEAL dd where dd.P_TRADE_ID = d1.TRADE_ID and dd.TRADE_STATUS = '03' ) )
) aa
and aa.matchType in (
#{item}
)
AND (aa.portfolioId IN
null) or aa.portfolioId in (
#{item} )
AND (aa.cstpTradeId IN
null) or aa.cstpTradeId in (
#{item} )
and aa.ps = #{ps}
and aa.tradeMarket = #{tradeMarket}
and aa.finprodMarketId = #{tradeMarket}
and aa.finprodMarketId = #{tradeMarket}
AND aa.tradeDate >= STR_TO_DATE(#{trdMatchInfoDateBegin},'%Y-%m-%d')
AND aa.tradeDate <= STR_TO_DATE(#{trdMatchInfoDateEnd},'%Y-%m-%d')
and aa.tradeAmt>=${priceAmt}
and aa.tradeAmt <=${priceAmt2}
and aa.repoTerm >= ${repoTerm}
and aa.repoTerm < ${repoTerm2}
